import { addLabelToTask, createLabel, createTask, getTasks } from 'wasp/client/operations'
import './Main.css'

type TaskWithLabels = Task & { labels: Label[] }

type LabelSelection = Record<number, number | ''>

export function MainPage() {
  const { data: tasks, isLoading, error, refetch } = useQuery(getTasks)
  const createTaskAction = useAction(createTask)
  const createLabelAction = useAction(createLabel)
  const addLabelToTaskAction = useAction(addLabelToTask)

  const [description, setDescription] = useState('')
  const [labelName, setLabelName] = useState('')
  const [labels, setLabels] = useState<Label[]>([])
  const [labelSelections, setLabelSelections] = useState<LabelSelection>({})

  useEffect(() => {
    if (!tasks) {
      return
    }

    const uniqueLabels = new Map<number, Label>()
    tasks.forEach((task) => {
      task.labels.forEach((label) => {
        uniqueLabels.set(label.id, label)
      })
    })

    setLabels((prevLabels) => {
      const merged = new Map<number, Label>()
      prevLabels.forEach((label) => merged.set(label.id, label))
      uniqueLabels.forEach((label) => merged.set(label.id, label))
      return Array.from(merged.values())
    })
  }, [tasks])

  const labelOptions = useMemo(() => {
    return labels.sort((a, b) => a.name.localeCompare(b.name))
  }, [labels])

  const handleCreateTask = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (!description.trim()) {
      return
    }

    await createTaskAction({ description: description.trim() })
    setDescription('')
    await refetch()
  }

  const handleCreateLabel = async (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (!labelName.trim()) {
      return
    }

    const newLabel = await createLabelAction({ name: labelName.trim() })
    setLabelName('')
    setLabels((prev) => {
      if (prev.some((label) => label.id === newLabel.id)) {
        return prev
      }
      return [...prev, newLabel]
    })
  }

  const handleAddLabel = async (taskId: number) => {
    const selectedLabelId = labelSelections[taskId]
    if (!selectedLabelId) {
      return
    }

    await addLabelToTaskAction({ taskId, labelId: selectedLabelId })
    setLabelSelections((prev) => ({ ...prev, [taskId]: '' }))
    await refetch()
  }

  const handleLabelSelect = (taskId: number, value: string) => {
    setLabelSelections((prev) => ({
      ...prev,
      [taskId]: value ? Number(value) : ''
    }))
  }

  return (
    <main className="container">
      <header>
        <h1>Tasks & Labels</h1>
        <p>Manage many-to-many labels for your tasks.</p>
      </header>

      <section className="panel">
        <div className="forms">
          <form onSubmit={handleCreateTask} className="form">
            <h2>Create task</h2>
            <input
              type="text"
              value={description}
              onChange={(event) => setDescription(event.target.value)}
              placeholder="Task description"
            />
            <button type="submit">Add task</button>
          </form>

          <form onSubmit={handleCreateLabel} className="form">
            <h2>Create label</h2>
            <input
              type="text"
              value={labelName}
              onChange={(event) => setLabelName(event.target.value)}
              placeholder="Label name"
            />
            <button type="submit">Add label</button>
          </form>
        </div>
      </section>

      <section className="panel">
        <h2>Tasks</h2>
        {isLoading && <p>Loading tasks...</p>}
        {error && <p className="error">Failed to load tasks.</p>}
        {!isLoading && tasks && tasks.length === 0 && <p>No tasks yet.</p>}

        <ul className="task-list">
          {(tasks ?? []).map((task: TaskWithLabels) => (
            <li key={task.id} className="task-card">
              <div>
                <h3>{task.description}</h3>
                {task.labels.length > 0 ? (
                  <div className="labels">
                    {task.labels.map((label) => (
                      <span key={label.id} className="label-pill">
                        {label.name}
                      </span>
                    ))}
                  </div>
                ) : (
                  <p className="muted">No labels assigned.</p>
                )}
              </div>

